const DAILY_20261002=[{"id":"smorrebrod","n":"Smørrebrød (Danish Open-Faced Rye Sandwich)","c":"Denmark","f":"🇩🇰","m":20,"x":["rye bread","herring","egg","cucumber","onion","mayonnaise"],"s":["Toast or lightly butter the rye bread so it stays firm.","Arrange drained herring, sliced boiled egg, cucumber, and onion on top.","Add a small spoonful of mayonnaise without covering the other toppings.","Finish with pepper and serve immediately as an open sandwich."],"co":"#b84b45","source":"https://www.visitdenmark.com/denmark/things-to-do/eat-drink/traditional-danish-food","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"frikadeller","n":"Frikadeller (Danish Pork and Veal Meatballs)","c":"Denmark","f":"🇩🇰","m":35,"x":["pork","veal","flour","milk","egg","onion"],"s":["Mix minced pork and veal with finely chopped onion.","Stir in egg, flour, milk, salt, and pepper to make a soft mixture.","Shape oval meatballs with a spoon and place them in a hot pan.","Brown on both sides, then lower the heat and cook until the centres are done."],"co":"#a76d48","source":"https://www.visitdenmark.com/denmark/things-to-do/eat-drink/traditional-danish-food","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"carbonnade-flamande","n":"Carbonnade Flamande (Belgian Beer-Braised Beef)","c":"Belgium","f":"🇧🇪","m":130,"x":["beef","onion","beer","beef broth","bread","mustard"],"s":["Brown the beef in batches and set it aside.","Cook the onion slowly until deep golden, then return the beef.","Add beer and broth, and place mustard-spread bread on top.","Cover and simmer gently until the beef is tender and the sauce is rich."],"co":"#7a4d32","source":"https://www.visitflanders.com/it/scopri-le-fiandre/delizie-culinarie-e-birra-belga/patatine-fritte","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"brussels-waffle","n":"Brussels Waffle (Belgian Light Yeast Waffle)","c":"Belgium","f":"🇧🇪","m":50,"x":["flour","milk","egg","butter","sugar","yeast"],"s":["Dissolve the yeast in warm milk and let it foam.","Whisk in egg, melted butter, sugar, and flour to make a smooth batter.","Rest the batter until visibly airy.","Cook in a hot waffle iron until crisp outside and light inside."],"co":"#d3a343","source":"https://www.visitflanders.com/en/stories/flemish-street-food-every-taste","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"crni-rizot","n":"Crni Rižot (Croatian Cuttlefish Black Risotto)","c":"Croatia","f":"🇭🇷","m":50,"x":["rice","cuttlefish","olive oil","onion","garlic","fish stock"],"s":["Clean and dice the cuttlefish, reserving its ink if available.","Soften onion and garlic in olive oil, then add the cuttlefish.","Stir in rice and add hot fish stock gradually while stirring.","Mix in the ink and cook until the rice is creamy but still slightly firm."],"co":"#343f49","source":"https://croatia.hr/en-gb/food-and-drink/black-risotto","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"pasticada","n":"Pašticada (Croatian Dalmatian Beef Stew)","c":"Croatia","f":"🇭🇷","m":180,"x":["beef","red wine","onion","carrot","tomato","prunes"],"s":["Marinate the beef with wine and aromatics, then pat it dry.","Brown the beef and soften onion and carrot in the same pot.","Add tomato, marinade, and prunes, then cover and braise slowly.","Slice the tender beef and blend or reduce the sauce before serving."],"co":"#8f3f38","source":"https://croatia.hr/en-gb/food-and-drink/pasticada","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"encebollado","n":"Encebollado (Ecuadorian Tuna and Cassava Soup)","c":"Ecuador","f":"🇪🇨","m":55,"x":["tuna","cassava","tomato","red onion","lime","cilantro"],"s":["Simmer the tuna in water with tomato and aromatics until cooked.","Remove and flake the tuna, then cook cassava pieces in the broth until tender.","Return the tuna and adjust the broth with lime and salt.","Top each bowl with thin red onion and cilantro."],"co":"#d39c37","source":"https://ecuador.travel/en/elementor-5966-2-2/","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"locro-de-papa","n":"Locro de Papa (Ecuadorian Potato and Cheese Soup)","c":"Ecuador","f":"🇪🇨","m":45,"x":["potato","cheese","milk","onion","garlic","avocado"],"s":["Soften onion and garlic in a pot without browning.","Add potato and water, then simmer until very tender.","Mash part of the potato in the pot and stir in milk and cheese.","Season gently and serve with sliced avocado."],"co":"#d6b44b","source":"https://ecuador.travel/what-to-eat-gastronomia/","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"rheinischer-sauerbraten","n":"Rheinischer Sauerbraten (German Marinated Beef Roast)","c":"Germany","f":"🇩🇪","m":180,"x":["beef","red wine","vinegar","onion","carrot","ginger"],"s":["Marinate the beef with wine, vinegar, onion, carrot, and spices in advance.","Remove and dry the beef, then brown it on all sides.","Add the strained marinade and vegetables and braise slowly until tender.","Rest and slice the beef, then reduce and balance the tangy sauce."],"co":"#755047","source":"https://www.germany.travel/en/experience-enjoy/german-cuisine.html","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."},{"id":"kartoffelpuffer","n":"Kartoffelpuffer (German Crispy Potato Pancakes)","c":"Germany","f":"🇩🇪","m":30,"x":["potato","onion","egg","flour","olive oil","apple"],"s":["Grate potato and onion and squeeze out as much liquid as possible.","Mix with egg, flour, salt, and pepper.","Spoon thin portions into hot oil and flatten them.","Fry until crisp and golden on both sides, then serve with apple."],"co":"#b78a45","source":"https://www.germany.travel/de/erleben-geniessen/kartoffel.html","license":"WorldCook original recipe text; factual dish reference cited","sourceNote":"Dish identity and characteristic ingredients checked against the cited source; wording, quantities, and steps independently authored for this product."}];
