Object.assign(window.RECIPE_I18N,{"smorrebrod":{"ko":["스뫼레브뢰드(덴마크식 오픈 호밀 샌드위치)",["호밀빵을 살짝 굽거나 버터를 발라 단단하게 준비합니다.","물기를 뺀 청어, 삶은 달걀, 오이, 양파를 올립니다.","다른 재료를 가리지 않게 마요네즈를 조금 얹습니다.","후추로 마무리하고 오픈 샌드위치로 바로 냅니다."]],"es":["Smørrebrød (sándwich danés abierto de centeno)",["Tuesta o unta ligeramente el pan de centeno.","Coloca arenque, huevo cocido, pepino y cebolla.","Añade poca mayonesa sin tapar los ingredientes.","Termina con pimienta y sirve abierto."]],"ja":["スモーブロー（デンマーク風オープンライ麦サンド）",["ライ麦パンを軽く焼くかバターを塗ります。","水気を切ったにしん、ゆで卵、きゅうり、玉ねぎをのせます。","具を隠さないようマヨネーズを少量添えます。","こしょうで仕上げ、すぐに盛ります。"]],"zh":["丹麦开放式黑麦三明治",["黑麦面包略烤或薄涂黄油，使其结实。","铺上沥干鲱鱼、水煮蛋、黄瓜和洋葱。","加入少量蛋黄酱，不遮住配料。","撒胡椒，立即开放式上桌。"]]},"frikadeller":{"ko":["프리카델레르(덴마크식 돼지고기·송아지고기 완자)",["다진 돼지고기와 송아지고기에 잘게 썬 양파를 섞습니다.","달걀, 밀가루, 우유, 소금, 후추를 넣어 부드럽게 반죽합니다.","숟가락으로 타원형을 만들어 뜨거운 팬에 올립니다.","양면을 노릇하게 익히고 불을 줄여 속까지 완전히 익힙니다."]],"es":["Frikadeller (albóndigas danesas de cerdo y ternera)",["Mezcla cerdo, ternera y cebolla picada.","Añade huevo, harina, leche, sal y pimienta.","Forma albóndigas ovaladas con una cuchara.","Dora y termina de cocinar a fuego bajo."]],"ja":["フリカデラー（デンマーク風豚肉と仔牛肉のミートボール）",["豚ひき肉と仔牛肉に刻み玉ねぎを混ぜます。","卵、小麦粉、牛乳、塩、こしょうを加えます。","スプーンで楕円形にして熱いフライパンに置きます。","両面を焼き、弱火で中心まで火を通します。"]],"zh":["丹麦肉丸（猪肉小牛肉丸）",["猪肉末、小牛肉末和碎洋葱混合。","加入鸡蛋、面粉、牛奶、盐和胡椒。","用勺塑成椭圆肉丸，放入热锅。","两面煎黄后转小火煎熟中心。"]]},"carbonnade-flamande":{"ko":["카르보나드 플라망드(벨기에식 맥주 쇠고기찜)",["쇠고기를 나누어 노릇하게 익힌 뒤 꺼냅니다.","양파를 진한 황금색이 될 때까지 천천히 볶고 고기를 다시 넣습니다.","맥주와 육수를 붓고 머스터드를 바른 빵을 위에 올립니다.","뚜껑을 덮어 고기가 부드럽고 소스가 진해질 때까지 끓입니다."]],"es":["Carbonnade flamande (ternera belga braseada con cerveza)",["Dora la carne por tandas.","Carameliza la cebolla y devuelve la carne.","Añade cerveza y caldo y pon pan con mostaza encima.","Tapa y cocina hasta que la carne esté tierna."]],"ja":["カルボナード・フラマンド（ベルギー風牛肉のビール煮）",["牛肉を数回に分けて焼き、取り出します。","玉ねぎを濃いきつね色まで炒め、牛肉を戻します。","ビールとだしを加え、マスタードを塗ったパンをのせます。","ふたをして肉が柔らかくソースが濃くなるまで煮ます。"]],"zh":["佛兰德啤酒炖牛肉",["牛肉分批煎上色后取出。","洋葱慢炒至深金黄，放回牛肉。","加入啤酒和高汤，上放涂芥末的面包。","盖锅小火炖至牛肉软嫩、酱汁浓郁。"]]},"brussels-waffle":{"ko":["브뤼셀 와플(벨기에식 가벼운 이스트 와플)",["따뜻한 우유에 이스트를 풀어 거품이 생기게 둡니다.","달걀, 녹인 버터, 설탕, 밀가루를 넣어 매끈하게 섞습니다.","반죽에 공기가 차오를 때까지 휴지합니다.","달군 와플 기계에서 겉은 바삭하고 속은 가볍게 굽습니다."]],"es":["Gofre de Bruselas (gofre belga ligero con levadura)",["Disuelve la levadura en leche tibia.","Añade huevo, mantequilla, azúcar y harina.","Deja reposar hasta que la masa esté aireada.","Cocina en gofrera hasta crujiente."]],"ja":["ブリュッセルワッフル（ベルギー風軽い発酵ワッフル）",["温かい牛乳に酵母を溶かし、泡立たせます。","卵、溶かしバター、砂糖、小麦粉を混ぜます。","生地がふんわりするまで休ませます。","ワッフルメーカーで外はカリッと中は軽く焼きます。"]],"zh":["布鲁塞尔华夫饼（比利时发酵轻质华夫）",["酵母溶于温牛奶，静置起泡。","加入鸡蛋、融化黄油、糖和面粉搅匀。","发至面糊充满气泡。","华夫机烤至外脆内松。"]]},"crni-rizot":{"ko":["크르니 리조트(크로아티아식 오징어 먹물 리소토)",["갑오징어를 손질해 썰고 가능하면 먹물을 남깁니다.","올리브유에 양파와 마늘을 볶고 갑오징어를 넣습니다.","쌀을 넣고 뜨거운 생선 육수를 조금씩 부으며 저어 익힙니다.","먹물을 섞고 쌀이 크리미하면서 약간 씹힐 때 마칩니다."]],"es":["Crni rižot (risotto negro croata de sepia)",["Limpia y corta la sepia y reserva la tinta.","Ablanda cebolla y ajo y añade la sepia.","Agrega arroz y caldo caliente poco a poco.","Mezcla la tinta y cocina hasta cremoso."]],"ja":["ツルニ・リジョット（クロアチア風コウイカの黒リゾット）",["コウイカを処理して切り、墨を残します。","オリーブ油で玉ねぎとにんにくを炒め、イカを加えます。","米を加え、温かい魚だしを少しずつ入れます。","墨を混ぜ、米がクリーミーで少し歯ごたえが残るまで煮ます。"]],"zh":["克罗地亚墨鱼黑烩饭",["墨鱼清理切块，保留墨汁。","橄榄油炒软洋葱和大蒜，加入墨鱼。","加入米，分次倒入热鱼汤并搅拌。","拌入墨汁，煮至绵滑且米芯微硬。"]]},"pasticada":{"ko":["파슈티차다(크로아티아 달마티아식 쇠고기 스튜)",["쇠고기를 포도주와 향신채에 재운 뒤 물기를 닦습니다.","고기를 노릇하게 굽고 같은 냄비에서 양파와 당근을 볶습니다.","토마토, 재운 국물, 자두를 넣고 천천히 푹 익힙니다.","부드러운 고기를 썰고 소스를 갈거나 졸여 함께 냅니다."]],"es":["Pašticada (estofado dálmata croata de ternera)",["Marina la carne con vino y aromáticos.","Dórala y cocina cebolla y zanahoria.","Añade tomate, marinada y ciruelas y brasea lentamente.","Corta la carne y reduce o tritura la salsa."]],"ja":["パシュティツァダ（クロアチア・ダルマチア風牛肉煮込み）",["牛肉をワインと香味野菜で漬け、水気を拭きます。","牛肉を焼き、同じ鍋で玉ねぎとにんじんを炒めます。","トマト、漬け汁、プルーンを加えてゆっくり煮込みます。","柔らかい肉を切り、ソースを攪拌または煮詰めます。"]],"zh":["帕什蒂察（克罗地亚达尔马提亚炖牛肉）",["牛肉用红酒和香料腌制后擦干。","牛肉煎香，同锅炒洋葱和胡萝卜。","加入番茄、腌汁和西梅，慢炖至软。","牛肉切片，酱汁搅打或收浓。"]]},"encebollado":{"ko":["엔세보야도(에콰도르식 참치·카사바 수프)",["참치를 토마토와 향신채를 넣은 물에 익힙니다.","참치를 꺼내 결대로 찢고 육수에서 카사바를 부드럽게 익힙니다.","참치를 다시 넣고 라임과 소금으로 국물 맛을 맞춥니다.","얇게 썬 적양파와 고수를 올립니다."]],"es":["Encebollado (sopa ecuatoriana de atún y yuca)",["Cuece el atún con tomate y aromáticos.","Desmenuza el atún y cuece la yuca en el caldo.","Devuelve el pescado y ajusta con lima y sal.","Termina con cebolla roja y cilantro."]],"ja":["エンセボジャード（エクアドル風まぐろとキャッサバのスープ）",["まぐろをトマトと香味野菜入りの水で煮ます。","まぐろをほぐし、煮汁でキャッサバを柔らかく煮ます。","まぐろを戻し、ライムと塩で味を整えます。","薄切り紫玉ねぎとコリアンダーをのせます。"]],"zh":["恩塞博亚多（厄瓜多尔金枪鱼木薯汤）",["金枪鱼与番茄和香料加水煮熟。","鱼肉取出撕碎，木薯在汤中煮软。","放回鱼肉，用青柠和盐调味。","撒细切红洋葱和香菜。"]]},"locro-de-papa":{"ko":["로크로 데 파파(에콰도르식 감자 치즈수프)",["냄비에서 양파와 마늘을 갈색 나지 않게 부드럽게 볶습니다.","감자와 물을 넣어 매우 부드러워질 때까지 끓입니다.","감자 일부를 냄비에서 으깨고 우유와 치즈를 섞습니다.","약하게 간하고 아보카도 조각을 곁들입니다."]],"es":["Locro de papa (sopa ecuatoriana de patata y queso)",["Ablanda cebolla y ajo sin dorar.","Añade patata y agua y cuece hasta muy tierna.","Machaca parte y añade leche y queso.","Sazona y sirve con aguacate."]],"ja":["ロクロ・デ・パパ（エクアドル風じゃがいもチーズスープ）",["玉ねぎとにんにくを色づけず柔らかくします。","じゃがいもと水を加え、非常に柔らかく煮ます。","一部をつぶし、牛乳とチーズを混ぜます。","軽く味を整え、アボカドを添えます。"]],"zh":["厄瓜多尔土豆奶酪汤",["洋葱和大蒜炒软，不上色。","加入土豆和水，煮至非常软。","压碎部分土豆，拌入牛奶和奶酪。","轻调味，配牛油果片。"]]},"rheinischer-sauerbraten":{"ko":["라인식 자우어브라텐(독일식 새콤한 쇠고기 로스트)",["쇠고기를 포도주, 식초, 양파, 당근, 향신료에 미리 재웁니다.","고기를 꺼내 닦고 모든 면을 노릇하게 익힙니다.","거른 재운 국물과 채소를 넣어 부드러워질 때까지 천천히 익힙니다.","고기를 쉬게 한 뒤 썰고 새콤한 소스를 졸여 균형을 맞춥니다."]],"es":["Sauerbraten renano (asado alemán de ternera marinada)",["Marina la carne con vino, vinagre y verduras.","Sécala y dórala por todos lados.","Añade marinada colada y verduras y brasea.","Reposa, corta y reduce la salsa ácida."]],"ja":["ライン風ザウアーブラーテン（ドイツ風マリネ牛肉ロースト）",["牛肉をワイン、酢、玉ねぎ、にんじん、香辛料で漬けます。","取り出して水気を拭き、全面を焼きます。","漉した漬け汁と野菜を加え、柔らかく煮込みます。","休ませて切り、酸味のあるソースを煮詰めます。"]],"zh":["莱茵酸味炖牛肉",["牛肉用红酒、醋、洋葱、胡萝卜和香料腌制。","取出擦干，各面煎香。","加入过滤腌汁和蔬菜，慢炖至软。","静置切片，收浓并平衡酸味酱汁。"]]},"kartoffelpuffer":{"ko":["카르토펠푸퍼(독일식 바삭한 감자전)",["감자와 양파를 갈아 물기를 최대한 짭니다.","달걀, 밀가루, 소금, 후추를 섞습니다.","뜨거운 기름에 얇게 떠 넣고 눌러 폅니다.","양면을 바삭하고 노릇하게 익혀 사과와 냅니다."]],"es":["Kartoffelpuffer (tortitas alemanas crujientes de patata)",["Ralla patata y cebolla y exprime.","Mezcla con huevo, harina, sal y pimienta.","Pon porciones finas en aceite caliente.","Dora ambos lados y sirve con manzana."]],"ja":["カルトッフェルプッファー（ドイツ風カリカリじゃがいもパンケーキ）",["じゃがいもと玉ねぎをすりおろし、水分を絞ります。","卵、小麦粉、塩、こしょうを混ぜます。","熱い油に薄く落として平らにします。","両面をカリッと焼き、りんごを添えます。"]],"zh":["德国香脆土豆饼",["土豆和洋葱擦丝，尽量挤干。","加入鸡蛋、面粉、盐和胡椒。","薄勺入热油并压平。","两面煎脆金黄，配苹果。"]]}});
